<script lang="ts">
  import { client, site } from '$lib/api/client.svelte'
  import type { CommentResponse } from '$lib/api/types'
  import { profile } from '$lib/app/auth'
  import { errorMessage } from '$lib/app/error'

  import Markdown from '$lib/app/markdown/Markdown.svelte'
  import MarkdownEditor from '$lib/app/markdown/MarkdownEditor.svelte'
  import { placeholders } from '$lib/app/util.svelte'
  import { Button, Menu, MenuButton, toast } from 'mono-svelte'
  import { ArrowUp, Icon, Language, XMark } from 'svelte-hero-icons/dist'
  import type { ClassValue, HTMLTextareaAttributes } from 'svelte/elements'

  interface Props extends Omit<HTMLTextareaAttributes, 'oncancel'> {
    postId: number
    parentId?: number | undefined
    locked?: boolean
    banned?: boolean
    rows?: number
    placeholder?: string | undefined
    value?: string
    actions?: boolean
    tools?: boolean
    preview?: boolean
    class?: ClassValue
    required?: boolean
    id?: string
    label?: string
    editing?: boolean
    oncomment?: (comment: CommentResponse) => void
    onconfirm?: (value: string) => void
    oncancel?: (cancel: boolean) => void
  }

  let {
    postId,
    parentId = undefined,
    locked = false,
    banned = false,
    rows = 7,
    placeholder = undefined,
    value = $bindable(''),
    actions = true,
    preview: previewAction = true,
    editing = false,
    oncancel,
    oncomment,
    ...rest
  }: Props = $props()

  let loading = $state(false)
  let preview = false
  let language: number | undefined = $state()

  async function submit() {
    if (
      !profile.current?.user ||
      !profile.current?.jwt ||
      value == '' ||
      editing
    )
      return

    loading = true

    try {
      const response = await client().createComment({
        content: value,
        post_id: postId,
        parent_id: parentId,
        language_id: language,
      })
      oncomment?.(response)

      value = ''
    } catch (err) {
      console.error(err)
      toast({
        content: errorMessage(err as string),
        type: 'error',
      })
    }

    loading = false
  }
</script>

<form
  onsubmit={(e) => {
    e.preventDefault()
    submit()
  }}
  class="flex flex-col gap-2 relative"
>
  {#if preview}
    <div
      class="bg-slate-100 dark:bg-zinc-900 px-3 py-2.5 h-64 border
      border-slate-300 dark:border-zinc-700 rounded-md overflow-auto text-sm resize-y"
    >
      <Markdown source={value} />
    </div>
  {:else}
    <MarkdownEditor
      {...rest}
      {rows}
      placeholder={locked
        ?'This post is locked.'
        : banned
          ?'You are banned from this community.'
          : (placeholder ?? placeholders.get('comment'))}
      bind:value
      disabled={locked || loading || banned}
      previewButton={previewAction}
    >
      <Menu>
        {#snippet target(attachment)}
          <Button
            {@attach attachment}
            size="custom"
            rounding="xl"
            class="w-7.5 h-7.5"
            color={language != undefined ? 'primary' : 'ghost'}
            title=Languages
          >
            <Icon src={Language} size="14" micro />
          </Button>
        {/snippet}

        {#if site.data}
          <MenuButton
            class="min-h-[16px] py-0"
            onclick={() => (language = undefined)}
          >
            <Icon src={XMark} size="16" micro />
            Unset
          </MenuButton>
          {#each site.data?.all_languages as languageOption}
            <MenuButton
              class="min-h-[16px] py-0"
              onclick={() => {
                language = languageOption.id
              }}
            >
              {languageOption.name}
            </MenuButton>
          {/each}
        {/if}
      </Menu>
      <div class="flex-1"></div>
      {#if actions}
        <Button
          title=Cancel
          onclick={() => oncancel?.(true)}
          color="tertiary"
          size="square-md"
          rounding="xl"
        >
          <Icon
            src={XMark}
            size="16"
            micro
            class="text-slate-600 dark:text-zinc-400"
          />
        </Button>
        <Button
          submit
          color="primary"
          rounding="xl"
          {loading}
          disabled={locked || loading || banned}
          title=Submit
          size="square-lg"
        >
          {#snippet prefix()}
            <Icon src={ArrowUp} size="20" mini />
          {/snippet}
        </Button>
      {/if}
    </MarkdownEditor>
  {/if}
</form>
